import { Column, CreateDateColumn, Entity, Index, ManyToOne, PrimaryGeneratedColumn, Unique } from 'typeorm';
import { Delivery } from './delivery.entity';

export enum ReceiptType {
  GOODS_RECEIPT = 'goods_receipt',
  INVOICE = 'invoice',
  PAYMENT = 'payment',
}

export enum ReceiptSyncStatus {
  PENDING = 'pending',
  SYNCED = 'synced',
  FAILED = 'failed',
}

// clientId is generated by the Flutter app for each receipt. The unique constraint
// means a retried upload can never create a duplicate receipt.
@Entity('receipts')
@Unique(['deliveryId', 'clientId'])
export class Receipt {
  @PrimaryGeneratedColumn('uuid') id: string;

  @Column() clientId: string;

  @Column({ type: 'enum', enum: ReceiptType }) type: ReceiptType;

  @Column({ type: 'numeric', precision: 14, scale: 2, nullable: true }) amount: string | null;

  // Storage key (not a public URL). Files are served through an authenticated endpoint.
  @Column({ type: 'varchar', nullable: true }) fileKey: string | null;
  @Column({ type: 'varchar', nullable: true }) originalName: string | null;
  @Column({ type: 'varchar', nullable: true }) mimeType: string | null;
  @Column({ type: 'int', nullable: true }) sizeBytes: number | null;

  @Column({ type: 'varchar', nullable: true }) erpDocumentNumber: string | null;

  @Column({ type: 'enum', enum: ReceiptSyncStatus, default: ReceiptSyncStatus.PENDING })
  syncStatus: ReceiptSyncStatus;

  @Index()
  @ManyToOne(() => Delivery, (d) => d.receipts, { onDelete: 'CASCADE' })
  delivery: Delivery;

  @Column() deliveryId: string;

  @CreateDateColumn() createdAt: Date;
}
